-- Source: tools/answer-length-audit/fixes/gaswell.json (every item, its verdict and
-- its reason, old and new text side by side); generated by
-- tools/answer-length-audit/fix.py sql gaswell. Runs AFTER the 29 B4 length files
-- and any earlier fix file: every guard below is the text those leave behind.
--
-- GUARDS. Each changed row must match its OLD prompt, explanation and options
-- (md5) and answer_index exactly (then it is updated) or its NEW ones (already
-- applied, left alone). Anything else raises and the transaction rolls back.
-- Each insert must be absent (inserted) or present with the same text (left).
-- Each course ends at its asserted question count. SAFE TO RE-RUN.
-- ==========================================================================

do $$
declare
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_total   integer;
begin

  -- gaswell intermediate final - ord 7
  select case when md5(prompt) = '5267f16962bba16688da394b469b058a' and md5(coalesce(explanation, '')) = '22196d767f60c30d2b6870631d8741d0' and md5(options::text) = md5('["coleman at every station, because the function is handed the wellhead pressure by the profile and has no other pressure available to it.", "turner at every station, since each station inherits the correlation the study was run under and the study was run under a single name.", "coleman at 880.0 psia and 978.0 psia, then turner at 1090.0, 1218.0, 1350.0 and 1500.0 psia.", "coleman down to 4500.0 ft, then turner below it."]'::jsonb::text) and answer_index = 2 then 'old'
              when md5(prompt) = '76868169cb653562d32abfcd01f2dee7' and md5(coalesce(explanation, '')) = 'c90af1e4b9d532cd1bfe2df5809da4a6' and md5(options::text) = md5('["They were computed at the shoe from its pressure, temperature and z, which is why the controlling station carries them.", "They were read off the published water row and corrected for each station''s pressure, since tension falls as the gas gets denser.", "They were typed in as inputs, and nothing the modules know computes either of them.", "They are the Turner defaults loadingProfile applies to every well."]'::jsonb::text) and answer_index = 2 then 'new'
              else 'other' end
    into v_state
    from public.academy_quiz_questions where app_slug = 'gaswell' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 7 and active;
  if v_state is null then raise exception 'B4 fix gaswell refused: no row for gaswell intermediate final - ord 7'; end if;
  if v_state = 'other' then raise exception 'B4 fix gaswell refused: gaswell intermediate final - ord 7 matches neither its current nor its fixed form'; end if;
  if v_state = 'old' then
    update public.academy_quiz_questions set prompt = 'EBOCHA-5 is profiled with an interfacial tension of 62.0 dyne/cm and a liquid density of 66.2 lbm/ft3. Where did those two figures come from?', options = '["They were computed at the shoe from its pressure, temperature and z, which is why the controlling station carries them.", "They were read off the published water row and corrected for each station''s pressure, since tension falls as the gas gets denser.", "They were typed in as inputs, and nothing the modules know computes either of them.", "They are the Turner defaults loadingProfile applies to every well."]'::jsonb,
           answer_index = 2, explanation = 'Interfacial tension and liquid density are inputs, and neither is a function of anything the modules know. The published Turner properties, water at 60.0 dyne/cm and 67.0 lbm/ft3, are labelled starting points rather than correlations, and EBOCHA-5 does not use them.'
     where app_slug = 'gaswell' and tier = 'intermediate' and scope = 'final' and module_key is not distinct from null and ord = 7 and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'B4 fix gaswell refused: gaswell intermediate final - ord 7 updated % rows', v_count; end if;
    v_updated := v_updated + 1;
  end if;

  select count(*) into v_total from public.academy_quiz_questions where app_slug = 'gaswell' and active;
  if v_total <> 396 then raise exception 'B4 fix gaswell refused: gaswell holds % active questions, expected 396', v_total; end if;
  raise notice 'B4 fix gaswell: % of 1 rows written, the rest already carried the fixed text', v_updated;
end $$;
